#include "World/Modular/RARomanConstructionValidator.h"
static FRARomanGenerationMessage VMsg(FName C,const FString& M,bool E){FRARomanGenerationMessage R;R.Code=C;R.Message=M;R.bIsError=E;return R;}
bool URARomanConstructionValidator::ValidateParameters(const FRARomanBuildingParameters& P,TArray<FRARomanGenerationMessage>& W,TArray<FRARomanGenerationMessage>& E){return URARomanBuildingRuleLibrary::ValidateBuildingParameters(P,W,E);} 
bool URARomanConstructionValidator::ValidateCatalog(const URARomanModuleCatalog* C,TArray<FRARomanGenerationMessage>& W,TArray<FRARomanGenerationMessage>& E){ if(!C){W.Add(VMsg("NullCatalog",TEXT("Catalogo nullo consentito per layout astratti."),false)); return true;} C->ValidateCatalog(W,E); return E.Num()==0; }
bool URARomanConstructionValidator::ValidatePlacements(const TArray<FRARomanModulePlacement>& P,int32 Max,TArray<FRARomanGenerationMessage>& W,TArray<FRARomanGenerationMessage>& E){ if(P.Num()>Max)E.Add(VMsg("ModuleLimitExceeded",TEXT("Placement oltre MaximumModuleCount."),true)); for(const auto& X:P){ const FVector L=X.Transform.GetLocation(), S=X.Transform.GetScale3D(); if(!FMath::IsFinite(L.X)||!FMath::IsFinite(L.Y)||!FMath::IsFinite(L.Z)||!FMath::IsFinite(S.X)||!FMath::IsFinite(S.Y)||!FMath::IsFinite(S.Z))E.Add(VMsg("NonFiniteTransform",TEXT("Transform non finita."),true)); if(S.X<=0||S.Y<=0||S.Z<=0)E.Add(VMsg("InvalidScale",TEXT("Scala nulla o negativa."),true)); if(X.ModuleId.IsNone())W.Add(VMsg("AbstractModuleId",TEXT("Placement astratto senza ID asset specifico."),false)); } return E.Num()==0; }
